files.content:
:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --accent: #f4a261;
  --accent-hover: #e76f51;
  --text: #e0e0e0;
  --text-muted: #a0a0b0;
  --border-radius: 12px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  font-family: var(--font);
  font-size: 18px;
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}

.gallery-card {
  background: var(--card-bg);
  border-radius: var(--border-radius);
  padding: 40px 30px;
  max-width: 800px;
  width: 100%;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
  text-align: center;
}

h1 {
  font-size: 2rem;
  margin-bottom: 8px;
  color: var(--accent);
}

.subtitle {
  color: var(--text-muted);
  margin-bottom: 30px;
  font-size: 1rem;
}

.gallery {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 20px;
  justify-items: center;
}

.tile {
  width: 140px;
  height: 140px;
  border-radius: var(--border-radius);
  cursor: pointer;
  border: 3px solid transparent;
  transition: transform 0.2s, border-color 0.2s, box-shadow 0.2s;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
  background: #3a3a55;
}

.tile:hover {
  transform: scale(1.05);
  border-color: var(--accent);
  box-shadow: 0 0 15px rgba(244, 162, 97, 0.4);
}

.tile:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 3px;
}

.tile:active {
  transform: scale(0.98);
}

/* CSS-drawn tile patterns */
.tile-0 {
  background: linear-gradient(45deg, #f4a261 25%, transparent 25%),
              linear-gradient(-45deg, #f4a261 25%, transparent 25%),
              linear-gradient(45deg, transparent 75%, #f4a261 75%),
              linear-gradient(-45deg, transparent 75%, #f4a261 75%);
  background-size: 20px 20px;
  background-position: 0 0, 0 10px, 10px -10px, -10px 0;
}

.tile-1 {
  background: radial-gradient(circle at 30% 30%, #e76f51 15%, transparent 15%),
              radial-gradient(circle at 70% 70%, #e76f51 15%, transparent 15%),
              radial-gradient(circle at 30% 70%, #e76f51 15%, transparent 15%),
              radial-gradient(circle at 70% 30%, #e76f51 15%, transparent 15%),
              #2a2a40;
  background-size: 30px 30px;
}

.tile-2 {
  background: repeating-linear-gradient(0deg, #2a9d8f, #2a9d8f 10px, #264653 10px, #264653 20px);
}

.tile-3 {
  background: conic-gradient(from 0deg, #e9c46a, #f4a261, #e76f51, #e9c46a);
}

.tile-4 {
  background: linear-gradient(135deg, #264653 25%, #2a9d8f 25%, #2a9d8f 50%, #264653 50%, #264653 75%, #2a9d8f 75%);
  background-size: 40px 40px;
}

.tile-5 {
  background: radial-gradient(circle at 50% 50%, #f4a261 20%, transparent 20%),
              radial-gradient(circle at 50% 50%, #e76f51 40%, transparent 40%),
              radial-gradient(circle at 50% 50%, #e9c46a 60%, transparent 60%),
              #2a2a40;
  background-size: 60px 60px;
}

/* Modal */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.8);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 100;
  padding: 20px;
}

.modal {
  background: var(--card-bg);
  border-radius: var(--border-radius);
  padding: 30px;
  max-width: 500px;
  width: 100%;
  text-align: center;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.7);
  position: relative;
}

.modal-title {
  font-size: 1.5rem;
  color: var(--accent);
  margin-bottom: 20px;
}

.modal-art {
  width: 100%;
  aspect-ratio: 1;
  max-width: 300px;
  margin: 0 auto 20px;
  border-radius: var(--border-radius);
  background: #3a3a55;
  /* The tile class will be applied dynamically */
}

.modal-controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  background: var(--accent);
  color: #1e1e2f;
  border: none;
  border-radius: 8px;
  padding: 12px 24px;
  font-size: 1rem;
  font-family: var(--font);
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  min-width: 100px;
}

.btn:hover {
  background: var(--accent-hover);
}

.btn:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.96);
}

.btn-close {
  background: var(--text-muted);
  color: var(--bg);
}

.btn-close:hover {
  background: #c0c0d0;
}

[hidden] {
  display: none !important;
}

/* Responsive */
@media (max-width: 480px) {
  .gallery-card {
    padding: 24px 16px;
  }
  .gallery {
    grid-template-columns: repeat(2, 1fr);
  }
  .tile {
    width: 100%;
    height: auto;
    aspect-ratio: 1;
  }
  .modal {
    padding: 20px;
  }
  .btn {
    padding: 10px 16px;
    font-size: 0.95rem;
    min-width: 80px;
  }
}

const tiles = [
  { title: 'Diamond Pattern', className: 'tile-0' },
  { title: 'Dot Grid', className: 'tile-1' },
  { title: 'Stripes', className: 'tile-2' },
  { title: 'Conic Burst', className: 'tile-3' },
  { title: 'Chevron', className: 'tile-4' },
  { title: 'Radial Rings', className: 'tile-5' }
];

const gallery = document.getElementById('gallery');
const modalBackdrop = document.getElementById('modalBackdrop');
const modal = document.getElementById('modal');
const modalTitle = document.getElementById('modalTitle');
const modalArt = document.getElementById('modalArt');
const prevBtn = document.getElementById('prevBtn');
const nextBtn = document.getElementById('nextBtn');
const closeBtn = document.getElementById('closeBtn');

let currentIndex = 0;
let lastFocusedElement = null;

// Build gallery tiles
tiles.forEach((tile, index) => {
  const btn = document.createElement('button');
  btn.className = `tile ${tile.className}`;
  btn.setAttribute('aria-label', `View ${tile.title}`);
  btn.dataset.index = index;
  btn.addEventListener('click', () => openModal(index));
  gallery.appendChild(btn);
});

function openModal(index) {
  currentIndex = index;
  lastFocusedElement = document.activeElement;
  updateModal();
  modalBackdrop.hidden = false;
  closeBtn.focus();
  document.addEventListener('keydown', handleKeydown);
}

function closeModal() {
  modalBackdrop.hidden = true;
  document.removeEventListener('keydown', handleKeydown);
  if (lastFocusedElement) {
    lastFocusedElement.focus();
    lastFocusedElement = null;
  }
}

function updateModal() {
  const tile = tiles[currentIndex];
  modalTitle.textContent = tile.title;
  modalArt.className = `modal-art ${tile.className}`;
  modalArt.setAttribute('aria-label', tile.title);
}

function showPrev() {
  currentIndex = (currentIndex - 1 + tiles.length) % tiles.length;
  updateModal();
}

function showNext() {
  currentIndex = (currentIndex + 1) % tiles.length;
  updateModal();
}

function handleKeydown(e) {
  if (e.key === 'Escape') {
    e.preventDefault();
    closeModal();
  } else if (e.key === 'ArrowLeft') {
    e.preventDefault();
    showPrev();
  } else if (e.key === 'ArrowRight') {
    e.preventDefault();
    showNext();
  } else if (e.key === 'Tab') {
    // Focus trap within modal
    const focusable = modal.querySelectorAll('button');
    const first = focusable[0];
    const last = focusable[focusable.length - 1];
    if (e.shiftKey && document.activeElement === first) {
      e.preventDefault();
      last.focus();
    } else if (!e.shiftKey && document.activeElement === last) {
      e.preventDefault();
      first.focus();
    }
  }
}

prevBtn.addEventListener('click', showPrev);
nextBtn.addEventListener('click', showNext);
closeBtn.addEventListener('click', closeModal);

// Close on backdrop click
modalBackdrop.addEventListener('click', (e) => {
  if (e.target === modalBackdrop) {
    closeModal();
  }
});
